SELECT origin.post_id, count(*) last_people_num FROM tb_collaboration_attendance origin JOIN ( SELECT post_id, person_id, max( create_time ) create_time FROM tb_collaboration_attendance GROUP BY post_id, person_id ) tmp ON origin.post_id = tmp.post_id AND origin.person_id = tmp.person_id AND origin.create_time = tmp.create_time WHERE type = '上岗' AND origin.post_id in
#{item}
GROUP BY origin.post_id

SELECT post_id, max( create_time ) create_time FROM tb_collaboration_attendance WHERE type = '下岗' AND post_id in
#{item}
GROUP BY post_id

SELECT person_id FROM ( SELECT person_id, type, ROW_NUMBER() OVER (PARTITION BY person_id ORDER BY create_time DESC) as rn FROM tb_collaboration_attendance WHERE post_id = #{postId} AND person_id IN
#{personId}
) t WHERE rn = 1 AND type = '上岗'

SELECT post_id FROM ( SELECT post_id, person_id, type, ROW_NUMBER() OVER (PARTITION BY post_id, person_id ORDER BY create_time DESC) as rn FROM tb_collaboration_attendance WHERE post_id IN
#{postId}
AND person_id IN
#{personId}
) t WHERE rn = 1 AND type = '上岗' GROUP BY post_id
